def remove_forwarding(session):
    session.forwarding_installed = False

def release_resources(session):
    session.resources_allocated = False

def release_pdu_session(store, session_id):
    session = store.get(session_id)
    if session.state not in ("active", "modifying"):
        raise RuntimeError("Session cannot be released in its current state")
    session.state = "releasing"
    remove_forwarding(session)
    release_resources(session)
    session.state = "released"
    store.remove(session_id)

class PduSession:
    def __init__(self, session_id):
        self.session_id = session_id
        self.state = "requested"
        self.forwarding_installed = False

def validate_request(request):
    return bool(request.get("ue_id")) and bool(request.get("dnn"))

def reserve_resources(session, request):
    session.uplink_teid = request["uplink_teid"]
    session.downlink_teid = request["downlink_teid"]
    return True

def install_forwarding(session):
    session.forwarding_installed = True

def establish_pdu_session(store, request):
    if not validate_request(request):
        raise ValueError("Invalid session request")
    session = PduSession(request["session_id"])
    store.add(session)
    if not reserve_resources(session, request):
        store.remove(session.session_id)
        raise RuntimeError("Resource reservation failed")
    session.state = "resources_reserved"
    install_forwarding(session)
    session.state = "active"
    return session

def validate_delta(delta):
    if not delta:
        raise ValueError("Modification delta is empty")

def apply_qos_rules(session, qos_rules):
    session.qos_rules = list(qos_rules)

def update_session_parameters(session, delta):
    session.parameters.update(delta)

def modify_pdu_session(store, session_id, delta):
    session = store.get(session_id)
    if session.state != "active":
        raise RuntimeError("Session is not active")
    validate_delta(delta)
    session.state = "modifying"
    apply_qos_rules(session, delta.get("qos_rules", session.qos_rules))
    update_session_parameters(session, delta)
    session.state = "active"
    return session
